{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-cd",
  "version": "0.1.0",
  "type": "module",
  "description": "OpenCode TUI plugin for changing the current session directory",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui",
    "session-management",
    "session-migration",
    "workspace",
    "directory",
    "git"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/artempavlov/opencode-cd.git"
  },
  "homepage": "https://github.com/artempavlov/opencode-cd#readme",
  "bugs": {
    "url": "https://github.com/artempavlov/opencode-cd/issues"
  },
  "files": [
    "LICENSE",
    "README.md",
    "session-directory.ts",
    "session-migration.ts"
  ],
  "exports": {
    ".": {
      "types": "./session-directory.ts",
      "import": "./session-directory.ts"
    },
    "./tui": {
      "types": "./session-directory.ts",
      "import": "./session-directory.ts"
    }
  },
  "scripts": {
    "typecheck": "tsc",
    "test": "bun test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.18.25",
    "@opentui/core": "0.5.1",
    "@opentui/keymap": "0.5.1",
    "@opentui/solid": "0.5.1",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@types/node": "24.12.2",
    "typescript": "5.9.3"
  }
}
